`timescale 1ns / 1ps
// Member C simulation: compare RTL LFSR states and Q1.23 samples against
// vectors generated by: PYTHONPATH=sw python -m member_c.generate_vectors
module tb_lfsr;
    localparam integer NUM = 256;
    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg rst = 1'b1;
    reg enable = 1'b0;
    wire [22:0] state;
    wire signed [23:0] sample_out;
    wire sample_valid;

    reg [22:0] expected_state [0:NUM-1];
    reg [23:0] expected_sample [0:NUM-1];
    integer i;
    integer errors;

    lfsr dut (
        .clk(clk), .rst(rst), .enable(enable),
        .state(state), .sample_out(sample_out), .sample_valid(sample_valid)
    );

    initial begin
        errors = 0;
        $readmemh("sim/vectors/lfsr_state.hex", expected_state);
        $readmemh("sim/vectors/lfsr_sample.hex", expected_sample);

        repeat (3) @(negedge clk);
        rst = 1'b0;

        for (i = 0; i < NUM; i = i + 1) begin
            @(negedge clk);
            enable = 1'b1;
            @(posedge clk);
            #1;
            if (state !== expected_state[i]) begin
                $display("LFSR state mismatch i=%0d got=%h expected=%h", i, state, expected_state[i]);
                errors = errors + 1;
            end
            if (sample_out !== expected_sample[i]) begin
                $display("LFSR sample mismatch i=%0d got=%h expected=%h", i, sample_out, expected_sample[i]);
                errors = errors + 1;
            end
            if (sample_valid !== 1'b1) begin
                $display("LFSR sample_valid missing at i=%0d", i);
                errors = errors + 1;
            end
            @(negedge clk);
            enable = 1'b0;
        end

        if (errors == 0)
            $display("PASS: LFSR RTL matches all %0d Python reference samples", NUM);
        else
            $fatal(1, "FAIL: %0d LFSR mismatches", errors);
        $finish;
    end
endmodule
